package com.trampolim.api.career;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.server.ResponseStatusException;
import com.trampolim.api.BackendApplication;import com.trampolim.api.radar.RadarBridge;import com.trampolim.api.education.ProfessionalPassportService;
@SpringBootTest(classes=BackendApplication.class,webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"radar.bridge-secret=synthetic-professional-bridge-secret-0000000000","app.admin.emails=challenge-admin@example.test","operations.catalog-jobs-enabled=false","app.mail.enabled=false"})
class ProfessionalChallengePostgresTest {
 static final String KEY="synthetic-professional-bridge-secret-0000000000",ADMIN="challenge-admin@example.test";
 @Autowired CompanyCareerService companies;@Autowired ProfessionalChallengeService moderation;@Autowired CareerProjectsController candidates;@Autowired CareerPassportLinkController links;@Autowired ProfessionalPassportService passport;@Autowired CareerDeliveryWorker worker;@Autowired RadarBridge bridge;
 @Autowired @Qualifier("empresasJdbcTemplate")JdbcTemplate emp;@Autowired @Qualifier("jdbcTemplate")JdbcTemplate opp;@Autowired @Qualifier("capacitaJdbcTemplate")JdbcTemplate cap;@LocalServerPort int port;Object oldBase;
 record Owner(long company,String email){}record Definition(long id,CompanyCareerService.Challenge input){}
 @BeforeEach void init(){oldBase=ReflectionTestUtils.getField(bridge,"base");ReflectionTestUtils.setField(bridge,"base","http://127.0.0.1:"+port+"/api");}
 @AfterEach void restore(){ReflectionTestUtils.setField(bridge,"base",oldBase);}
 String person(JdbcTemplate db,boolean student){String email=UUID.randomUUID()+"@example.test";if(student)db.update("INSERT INTO student_users(email,password_hash,full_name,email_verified,account_status,education_stage,terms_accepted_at) VALUES (?,'synthetic','Pessoa sintética',TRUE,'ACTIVE','HIGH_SCHOOL',CURRENT_TIMESTAMP)",email);else db.update("INSERT INTO app_users(email,password_hash,full_name,email_verified,account_type) VALUES (?,'synthetic','Pessoa sintética',TRUE,'PERSON')",email);return email;}
 Owner owner(){String email=UUID.randomUUID()+"@example.test";long uid=emp.queryForObject("INSERT INTO company_users(email,password_hash,full_name,email_verified,account_status) VALUES (?,'synthetic','Responsável sintético',TRUE,'ACTIVE') RETURNING id",Long.class,email);long company=emp.queryForObject("INSERT INTO companies(owner_user_id,legal_name,trade_name,cnpj,phone,industry,address,city,state,verification_status) VALUES (?,'Empresa sintética','Empresa sintética',?,'fixture','fixture','fixture','Irecê','BA','APPROVED') RETURNING id",Long.class,uid,String.format("%014d",Math.abs(UUID.randomUUID().getLeastSignificantBits()%100000000000000L)));emp.update("INSERT INTO company_members(company_id,user_id,role) VALUES (?,?,'OWNER')",company,uid);return new Owner(company,email);}
 CompanyCareerService.Challenge input(String state,int revision){return new CompanyCareerService.Challenge("Desafio sintético","Exercício fictício exclusivamente no teste",List.of(new CompanyCareerService.Skill("sql",2)),List.of(new CompanyCareerService.Criterion("quality","Qualidade explicada",100)),70,"","","Participação voluntária. Autor mantém direitos. Apenas avaliação educacional; sem uso produtivo nem garantia de contratação.",Instant.now().plusSeconds(86400).truncatedTo(java.time.temporal.ChronoUnit.MILLIS),state,revision);}
 CompanyCareerService.Challenge state(CompanyCareerService.Challenge p,String status,int revision){return new CompanyCareerService.Challenge(p.title(),p.description(),p.skills(),p.criteria(),p.passPercent(),p.materials(),p.materialUrl(),p.terms(),p.deadline(),status,revision);}
 Definition draft(Owner o){var p=input("DRAFT",0);long id=((Number)companies.save(o.email(),0,p).get("id")).longValue();return new Definition(id,p);}
 int rev(Owner o,long id){return ((Number)companies.challenge(o.email(),id).get("revision")).intValue();}
 ProfessionalChallengeService.Proposal proposal(int revision,int limit){return new ProfessionalChallengeService.Proposal(revision,30,limit,true,true,true,true,true);}
 Definition published(Owner o,int limit){var d=draft(o);moderation.propose(o.email(),d.id(),proposal(1,limit));moderation.decide(ADMIN,d.id(),new ProfessionalChallengeService.Decision(2,true,"Revisão sintética independente confirma todos os critérios e salvaguardas.",true));companies.save(o.email(),d.id(),state(d.input(),"PUBLISHED",3));return d;}
 void code(int status,Runnable action){assertEquals(status,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
 CompanyCareerService.Delivery delivery(long id){return new CompanyCareerService.Delivery(2,UUID.randomUUID(),id,"Apelido escolhido","Resposta sintética para avaliação por critérios explícitos.","https://example.test/evidence",RadarBridge.hash(UUID.randomUUID().toString()),Instant.now(),((Number)emp.queryForMap("SELECT revision FROM company_challenges WHERE id=?",id).get("revision")).intValue());}
 UUID reviewed(Owner o,long id,int score){var d=delivery(id);companies.receive(KEY,d);companies.review(o.email(),id,d.receiptId(),new CompanyCareerService.Review(UUID.randomUUID(),Map.of("quality",score),"Feedback sintético segundo os critérios publicados."));return d.receiptId();}
 @Test void proposalRequiresSafeguardsAndIndependentApprovalBeforePublication(){var o=owner();code(409,()->companies.save(o.email(),0,input("PUBLISHED",0)));var d=draft(o);code(404,()->companies.publicChallenge(d.id()));code(400,()->moderation.propose(o.email(),d.id(),new ProfessionalChallengeService.Proposal(1,30,10,true,false,true,true,true)));var stranger=owner();code(404,()->moderation.propose(stranger.email(),d.id(),proposal(1,10)));moderation.propose(o.email(),d.id(),proposal(1,10));code(403,()->moderation.decide(o.email(),d.id(),new ProfessionalChallengeService.Decision(2,true,"Revisão sem permissão não pode publicar este desafio.",true)));code(400,()->moderation.decide(ADMIN,d.id(),new ProfessionalChallengeService.Decision(2,true,"Critérios precisam de revisão independente e fundamentada.",false)));moderation.decide(ADMIN,d.id(),new ProfessionalChallengeService.Decision(2,true,"Todos os critérios e direitos foram revisados neste teste.",true));companies.save(o.email(),d.id(),state(d.input(),"PUBLISHED",3));assertEquals("APPROVED",companies.publicChallenge(d.id()).get("review_status"));companies.save(o.email(),d.id(),state(d.input(),"DRAFT",4));code(409,()->companies.save(o.email(),d.id(),state(d.input(),"PUBLISHED",5)));assertEquals(2,emp.queryForObject("SELECT count(*) FROM company_challenge_moderation WHERE challenge_id=?",Integer.class,d.id()));}
 @Test void rejectedAndSuspendedChallengesStayUnavailable(){var o=owner();var d=draft(o);moderation.propose(o.email(),d.id(),proposal(1,10));moderation.decide(ADMIN,d.id(),new ProfessionalChallengeService.Decision(2,false,"Rejeitado por condições que exigem revisão do responsável.",false));code(409,()->companies.save(o.email(),d.id(),state(d.input(),"PUBLISHED",3)));var live=published(o,10);UUID receipt=reviewed(o,live.id(),85);assertEquals("ACTIVE",moderation.evidence(KEY,new CompanyCareerService.Receipt(1,receipt)).get("status"));moderation.suspend(ADMIN,live.id(),4,"Suspenso preventivamente para revisão das condições publicadas.");code(404,()->companies.publicChallenge(live.id()));assertEquals("INVALID",moderation.evidence(KEY,new CompanyCareerService.Receipt(1,receipt)).get("status"));}
 @Test void concurrentParticipationHonorsCapacityAndRetriesAreIdempotent()throws Exception{var o=owner();var d=published(o,1);var first=delivery(d.id());companies.receive(KEY,first);companies.receive(KEY,first);code(409,()->companies.receive(KEY,delivery(d.id())));assertEquals(1,emp.queryForObject("SELECT count(*) FROM company_challenge_submissions WHERE challenge_id=?",Integer.class,d.id()));var next=published(o,1);try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var jobs=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{start.await();try{companies.receive(KEY,delivery(next.id()));return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var f:jobs)codes.add(f.get(15,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);}}
 @Test void resultsUseBackendRubricAndCannotBeOverwritten(){var o=owner();var d=published(o,10);var answer=delivery(d.id());companies.receive(KEY,answer);code(400,()->companies.review(o.email(),d.id(),answer.receiptId(),new CompanyCareerService.Review(UUID.randomUUID(),Map.of("wrong",100),"Feedback válido mas critérios inválidos.")));var review=new CompanyCareerService.Review(UUID.randomUUID(),Map.of("quality",60),"Resposta precisa desenvolver os critérios apresentados.");companies.review(o.email(),d.id(),answer.receiptId(),review);companies.review(o.email(),d.id(),answer.receiptId(),review);assertEquals("INVALID",moderation.evidence(KEY,new CompanyCareerService.Receipt(1,answer.receiptId())).get("status"));code(409,()->companies.review(o.email(),d.id(),answer.receiptId(),new CompanyCareerService.Review(UUID.randomUUID(),Map.of("quality",100),"Tentativa indevida de substituir resultado anterior.")));code(401,()->moderation.evidence("wrong",new CompanyCareerService.Receipt(1,answer.receiptId())));code(404,()->companies.submissions(owner().email(),d.id(),null,20));}
 @Test void passportRequiresTwoConsentsAndSharingIsRecipientBoundAndRevocable(){var o=owner();var d=published(o,10);String candidate=person(opp,false),student=person(cap,true),otherStudent=person(cap,true);UUID receipt=UUID.randomUUID();var answer=new CareerProjectsController.Submit(receipt,d.id(),"Apelido voluntário","Resposta sintética privada, avaliada por critérios publicados.","https://example.test/private",true);candidates.submit(candidate,answer);assertEquals(1,worker.deliver());companies.review(o.email(),d.id(),receipt,new CompanyCareerService.Review(UUID.randomUUID(),Map.of("quality",90),"Feedback segundo a rubrica pública revisada."));code(400,()->links.issue(candidate,receipt,new CareerPassportLinkController.Consent(false)));code(404,()->links.issue(person(opp,false),receipt,new CareerPassportLinkController.Consent(true)));String token=links.issue(candidate,receipt,new CareerPassportLinkController.Consent(true)).get("token").toString();code(400,()->passport.claim(student,new ProfessionalPassportService.Import(token,false)));var result=passport.claim(student,new ProfessionalPassportService.Import(token,true));UUID id=(UUID)result.get("id");assertEquals("ACTIVE",result.get("status"));assertEquals(false,result.get("formalCertificate"));assertEquals(id,passport.claim(student,new ProfessionalPassportService.Import(token,true)).get("id"));code(404,()->passport.detail(otherStudent,id));code(404,()->passport.claim(otherStudent,new ProfessionalPassportService.Import(token,true)));assertFalse(result.toString().contains(candidate));assertFalse(result.toString().contains("Resposta sintética privada"));var share=passport.share(student,new ProfessionalPassportService.Share(id,o.email(),7,true));String shared=share.get("token").toString();code(404,()->passport.verify(KEY,new ProfessionalPassportService.Verify(shared,"other@example.test")));assertEquals("ACTIVE",passport.verify(KEY,new ProfessionalPassportService.Verify(shared,o.email())).get("status"));passport.revokeShare(student,(UUID)share.get("id"));code(404,()->passport.verify(KEY,new ProfessionalPassportService.Verify(shared,o.email())));links.revoke(candidate,id);assertEquals("INVALID",passport.detail(student,id).get("status"));}
 @Test void withdrawalInvalidatesProfessionalEvidenceEvenBeforeDelivery(){var o=owner();var d=published(o,10);String candidate=person(opp,false),student=person(cap,true);UUID receipt=UUID.randomUUID();candidates.submit(candidate,new CareerProjectsController.Submit(receipt,d.id(),"Apelido","Resposta sintética suficiente e sem dados privados.","",true));worker.deliver();companies.review(o.email(),d.id(),receipt,new CompanyCareerService.Review(UUID.randomUUID(),Map.of("quality",80),"Feedback que explica a avaliação por critérios."));String token=links.issue(candidate,receipt,new CareerPassportLinkController.Consent(true)).get("token").toString();UUID id=(UUID)passport.claim(student,new ProfessionalPassportService.Import(token,true)).get("id");candidates.withdraw(candidate,receipt);assertEquals("INVALID",passport.detail(student,id).get("status"));assertEquals(1L,((Number)moderation.indicators(o.email(),d.id()).get("received")).longValue());assertFalse(moderation.indicators(o.email(),d.id()).toString().contains(candidate));worker.deliver();assertEquals("INVALID",moderation.evidence(KEY,new CompanyCareerService.Receipt(1,receipt)).get("status"));}
 @Test void unavailableIntegrationDoesNotInventValidEvidenceAndAllowsRetry(){var o=owner();var d=published(o,10);String candidate=person(opp,false),student=person(cap,true);UUID receipt=UUID.randomUUID();candidates.submit(candidate,new CareerProjectsController.Submit(receipt,d.id(),"Apelido","Resposta sintética suficiente para este teste.","",true));worker.deliver();companies.review(o.email(),d.id(),receipt,new CompanyCareerService.Review(UUID.randomUUID(),Map.of("quality",90),"Feedback sintético com critérios explícitos."));String token=links.issue(candidate,receipt,new CareerPassportLinkController.Consent(true)).get("token").toString();String valid="http://127.0.0.1:"+port+"/api";ReflectionTestUtils.setField(bridge,"base","http://127.0.0.1:1/api");code(503,()->passport.claim(student,new ProfessionalPassportService.Import(token,true)));UUID reserved=cap.queryForObject("SELECT c.id FROM learning_professional_credentials c JOIN student_users u ON u.id=c.student_id WHERE u.email=?",UUID.class,student);ReflectionTestUtils.setField(bridge,"base",valid);assertEquals(reserved,passport.claim(student,new ProfessionalPassportService.Import(token,true)).get("id"));ReflectionTestUtils.setField(bridge,"base","http://127.0.0.1:1/api");assertEquals("UNAVAILABLE",passport.detail(student,reserved).get("status"));}

 @Test void companyRevocationInvalidatesPassportAndPreservesEvaluationHistory(){var o=owner();var d=published(o,10);String candidate=person(opp,false),student=person(cap,true);UUID receipt=UUID.randomUUID();candidates.submit(candidate,new CareerProjectsController.Submit(receipt,d.id(),"Apelido","Resposta sintética somente para este cenário.","",true));worker.deliver();companies.review(o.email(),d.id(),receipt,new CompanyCareerService.Review(UUID.randomUUID(),Map.of("quality",90),"Feedback sintético com critérios explícitos."));String token=links.issue(candidate,receipt,new CareerPassportLinkController.Consent(true)).get("token").toString();UUID id=(UUID)passport.claim(student,new ProfessionalPassportService.Import(token,true)).get("id");code(404,()->moderation.revokeReview(owner().email(),d.id(),receipt,"Revisão sem autorização não pode alterar o resultado."));moderation.revokeReview(o.email(),d.id(),receipt,"Resultado revogado por erro material documentado neste teste.");assertEquals("INVALID",passport.detail(student,id).get("status"));assertEquals(1,emp.queryForObject("SELECT count(*) FROM company_challenge_reviews WHERE receipt_id=? AND revoked_at IS NOT NULL",Integer.class,receipt));}
 @Test void moderationConcurrentDecisionsCannotOverrideEachOther()throws Exception{var o=owner();var d=draft(o);moderation.propose(o.email(),d.id(),proposal(1,10));try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var tasks=new ArrayList<Future<Integer>>();for(boolean approved:List.of(true,false))tasks.add(pool.submit(()->{start.await();try{moderation.decide(ADMIN,d.id(),new ProfessionalChallengeService.Decision(2,approved,"Decisão independente com justificativa registrada neste teste.",true));return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var t:tasks)codes.add(t.get(15,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);}}
 @Test void queuedAnswersCannotBeScoredAgainstAnotherRevision(){var o=owner();var d=published(o,10);var old=delivery(d.id());emp.update("UPDATE company_challenges SET revision=revision+1 WHERE id=?",d.id());code(409,()->companies.receive(KEY,old));assertEquals(0,emp.queryForObject("SELECT count(*) FROM company_challenge_submissions WHERE receipt_id=?",Integer.class,old.receiptId()));}
}
